/* Generated by crc (crc/fd/ctest.py). Do not edit.

   fd_ed25519_verify_batch_multi_msg and fd_ed25519_verify_batch_multi_msg_cached against the single
   verifies they agree with item by item (fd_ed25519_verify, fd_ed25519_verify_cached on the same
   cache), whichever build mode provides them (FD_ED25519_CRC, Local.mk): every CCTV and Wycheproof
   vector in every lane position among valid signatures and in the tail sizes, random batches of
   0 to 20 items mixing every failure kind over repeating keys as one cache fills and a
   four-entry one replaces; with --bench a line per entry point in test_ed25519's format. */

#include "../../fd_ballet.h"
#include "../fd_ed25519.h"
#include "../../hex/fd_hex.h"
#include <stdlib.h>
#include "../test_ed25519_cctv.c"
#include "../test_ed25519_wycheproof.c"

#define BATCH_MAX (20UL)
#define KEY_CNT   (6UL)
#define FILL_CNT  (8UL)
#define MSG_MAX   (1500UL)

static int g_bench = 0;

static void
log_bench( char const * descr,
           ulong        iter,
           long         dt ) {
  if( !iter ) return;
  float khz = 1e6f *(float)iter/(float)dt;
  float tau = (float)dt /(float)iter;
  FD_LOG_NOTICE(( "%-31s %11.3fK/s/core %10.3f ns/call", descr, (double)khz, (double)tau ));
}

static fd_ed25519_cache_t *
cache_create( ulong ent_cnt,
              ulong seed ) {
  void * mem = aligned_alloc( fd_ed25519_cache_align(), fd_ed25519_cache_footprint( ent_cnt ) );
  FD_TEST( mem );
  fd_ed25519_cache_t * cache = fd_ed25519_cache_join( fd_ed25519_cache_new( mem, ent_cnt, seed ) );
  FD_TEST( cache );
  return cache;
}

static void
cache_destroy( fd_ed25519_cache_t * cache ) {
  free( fd_ed25519_cache_delete( fd_ed25519_cache_leave( cache ) ) );
}

/* one item of a batch: the message, its signature and the key */
struct item { uchar const * msg; ulong msg_sz; uchar const * sig; uchar const * pub; };
typedef struct item item_t;

/* a signer: its keys and a valid item over a random message */
struct signer { uchar priv[32]; uchar pub[32]; uchar msg[256]; ulong msg_sz; uchar sig[64]; };
typedef struct signer signer_t;

static void
signer_init( signer_t *    s,
             fd_rng_t *    rng,
             fd_sha512_t * sha ) {
  for( ulong b=0; b<32UL; b++ ) s->priv[b] = fd_rng_uchar( rng );
  s->msg_sz = 32UL + fd_rng_ulong_roll( rng, 200UL );
  for( ulong b=0; b<s->msg_sz; b++ ) s->msg[b] = fd_rng_uchar( rng );
  fd_ed25519_public_from_private( s->pub, s->priv, sha );
  fd_ed25519_sign( s->sig, s->msg, s->msg_sz, s->pub, s->priv, sha );
  FD_TEST( fd_ed25519_verify( s->msg, s->msg_sz, s->sig, s->pub, sha )==FD_ED25519_SUCCESS );
}

static item_t
signer_item( signer_t const * s ) {
  item_t it = { s->msg, s->msg_sz, s->sig, s->pub };
  return it;
}

/* cnt items through both entry points: results[j] is fd_ed25519_verify's code, the cached form's
   fd_ed25519_verify_cached's on the same cache (the two agree); results beyond cnt are untouched */
static void
check_batch( item_t const         items[],
             ulong                cnt,
             fd_sha512_t *        shas[],
             fd_ed25519_cache_t * cache ) {
  uchar const * msgs[BATCH_MAX] = {0}, * sigs[BATCH_MAX] = {0}, * pubs[BATCH_MAX] = {0}; ulong szs[BATCH_MAX] = {0};
  int res[BATCH_MAX+1], resc[BATCH_MAX+1];
  FD_TEST( cnt<=BATCH_MAX );
  for( ulong j=0; j<cnt; j++ ) { msgs[j] = items[j].msg; szs[j] = items[j].msg_sz; sigs[j] = items[j].sig; pubs[j] = items[j].pub; }
  for( ulong j=0; j<=BATCH_MAX; j++ ) res[j] = resc[j] = 7;
  fd_ed25519_verify_batch_multi_msg( msgs, szs, sigs, pubs, shas, res, cnt );
  fd_ed25519_verify_batch_multi_msg_cached( msgs, szs, sigs, pubs, shas, resc, cnt, cache );
  for( ulong j=0; j<cnt; j++ ) {
    int want  = fd_ed25519_verify( msgs[j], szs[j], sigs[j], pubs[j], shas[j] );
    int wantc = fd_ed25519_verify_cached( msgs[j], szs[j], sigs[j], pubs[j], shas[j], cache );
    if( FD_UNLIKELY( want!=wantc ) ) FD_LOG_ERR(( "batch of %lu, item %lu: fd_ed25519_verify %d, fd_ed25519_verify_cached %d", cnt, j, want, wantc ));
    if( FD_UNLIKELY( res[j]!=want ) ) FD_LOG_ERR(( "batch of %lu, item %lu: fd_ed25519_verify_batch_multi_msg %d, fd_ed25519_verify %d", cnt, j, res[j], want ));
    if( FD_UNLIKELY( resc[j]!=wantc ) ) FD_LOG_ERR(( "batch of %lu, item %lu: fd_ed25519_verify_batch_multi_msg_cached %d, fd_ed25519_verify_cached %d", cnt, j, resc[j], wantc ));
  }
  FD_TEST( res[cnt]==7 && resc[cnt]==7 );
}

/* one vector among valid items: in every lane position of a batch of eight (one lane group) and
   at every position of the tail sizes 1, 2, 3 and 4 */
static void
check_vector( item_t               v,
              signer_t const       fill[FILL_CNT],
              fd_sha512_t *        shas[],
              fd_ed25519_cache_t * cache ) {
  static ulong const sizes[] = { 8UL, 1UL, 2UL, 3UL, 4UL };
  item_t items[FILL_CNT];
  for( ulong s=0; s<sizeof(sizes)/sizeof(sizes[0]); s++ ) {
    for( ulong pos=0; pos<sizes[s]; pos++ ) {
      for( ulong j=0; j<FILL_CNT; j++ ) items[j] = signer_item( &fill[j] );
      items[pos] = v;
      check_batch( items, sizes[s], shas, cache );
    }
  }
}

static void
test_vectors( fd_rng_t *           rng,
              fd_sha512_t *        shas[],
              fd_ed25519_cache_t * cache ) {
  static signer_t fill[FILL_CNT];
  for( ulong j=0; j<FILL_CNT; j++ ) signer_init( &fill[j], rng, shas[0] );
  ulong n = 0UL;
  for( fd_ed25519_verify_cctv_t const * p = ed25519_verify_cctvs; p->msg; p++, n++ ) {
    item_t v = { p->msg, p->msg_sz, p->sig, p->pub };
    check_vector( v, fill, shas, cache );
  }
  FD_LOG_NOTICE(( "cctv: %lu vectors in every position of batches of 8, 1, 2, 3 and 4: pass", n ));
  n = 0UL;
  for( fd_ed25519_verify_wycheproof_t const * p = ed25519_verify_wycheproofs; p->msg; p++, n++ ) {
    item_t v = { p->msg, p->msg_sz, p->sig, p->pub };
    check_vector( v, fill, shas, cache );
  }
  FD_LOG_NOTICE(( "wycheproof: %lu vectors in every position of batches of 8, 1, 2, 3 and 4: pass", n ));
}

/* the failure kinds of a random item: valid; the equation fails; R does not decode (or fails the
   equation); S not below L; A does not decode; A of small order; R of small order */
#define KIND_CNT (7UL)

static void
test_random( fd_rng_t *           rng,
             fd_sha512_t *        shas[],
             fd_ed25519_cache_t * cache,
             ulong                rounds ) {
  static ulong const lengths[] = { 0UL, 1UL, 31UL, 32UL, 33UL, 63UL, 64UL, 65UL, 100UL, 127UL, 128UL, 200UL, 500UL, 1024UL, 1231UL, 1232UL, 1233UL, 1500UL };
  static uchar const small[32] = { 1 };  /* y = 1: the identity */
  static signer_t keys[KEY_CNT];
  static uchar msg[BATCH_MAX][MSG_MAX+1], sig[BATCH_MAX][64], pub[BATCH_MAX][32];
  item_t items[BATCH_MAX];
  for( ulong k=0; k<KEY_CNT; k++ ) signer_init( &keys[k], rng, shas[0] );
  ulong kinds[KIND_CNT] = { 0 };
  for( ulong round=0; round<rounds; round++ ) {
    for( ulong cnt=0; cnt<=BATCH_MAX; cnt++ ) {
      for( ulong j=0; j<cnt; j++ ) {
        signer_t const * k = &keys[ fd_rng_ulong_roll( rng, KEY_CNT ) ];
        ulong sz = lengths[ fd_rng_ulong_roll( rng, sizeof(lengths)/sizeof(lengths[0]) ) ];
        for( ulong b=0; b<sz; b++ ) msg[j][b] = fd_rng_uchar( rng );
        fd_memcpy( pub[j], k->pub, 32UL );
        fd_ed25519_sign( sig[j], msg[j], sz, k->pub, k->priv, shas[j] );
        /* valid items twice as often as each failure kind */
        ulong kind = fd_rng_ulong_roll( rng, KIND_CNT+1UL ); kind = kind ? kind-1UL : 0UL;
        kinds[kind]++;
        switch( kind ) {
        case 1UL: sig[j][5]  = (uchar)(sig[j][5] ^ 1);     break;
        case 2UL: sig[j][0]  = (uchar)(sig[j][0] ^ 1);     break;
        case 3UL: sig[j][63] = (uchar)(sig[j][63] | 0x80); break;
        case 4UL: pub[j][3]  = (uchar)(pub[j][3] ^ 1);     break;
        case 5UL: fd_memcpy( pub[j], small, 32UL ); break;
        case 6UL: fd_memcpy( sig[j], small, 32UL ); break;
        default: break;
        }
        item_t it = { sz ? msg[j] : NULL, sz, sig[j], pub[j] };
        items[j] = it;
      }
      check_batch( items, cnt, shas, cache );
    }
  }
  FD_LOG_NOTICE(( "random batches of 0..%lu over %lu keys, %lu rounds (%lu valid items, %lu %lu %lu %lu %lu %lu failing): pass",
                  BATCH_MAX, KEY_CNT, rounds, kinds[0], kinds[1], kinds[2], kinds[3], kinds[4], kinds[5], kinds[6] ));
}

/* a line per entry point: ns per signature, 128-byte messages, one signer per item (the cached
   form after its keys were inserted) */
static void
bench( fd_rng_t *    rng,
       fd_sha512_t * shas[] ) {
  static signer_t keys[16];
  uchar const * msgs[16], * sigs[16], * pubs[16]; ulong szs[16]; int res[16];
  static uchar msg[16][128];
  for( ulong j=0; j<16UL; j++ ) {
    signer_init( &keys[j], rng, shas[0] );
    for( ulong b=0; b<128UL; b++ ) msg[j][b] = fd_rng_uchar( rng );
    fd_ed25519_sign( keys[j].sig, msg[j], 128UL, keys[j].pub, keys[j].priv, shas[0] );
    msgs[j] = msg[j]; szs[j] = 128UL; sigs[j] = keys[j].sig; pubs[j] = keys[j].pub;
  }
  static ulong const counts[] = { 1UL, 4UL, 8UL, 16UL };
  fd_ed25519_cache_t * cache = cache_create( 64UL, 5UL );
  /* pointers to the arrays: what the loops forget between iterations */
  uchar const * const * pm = msgs; uchar const * const * ps = sigs; uchar const * const * pp = pubs; ulong const * pz = szs;
  char cstr[128];
  for( ulong c=0; c<sizeof(counts)/sizeof(counts[0]); c++ ) {
    ulong n = counts[c], iter = 10000UL/n;
    fd_ed25519_verify_batch_multi_msg( msgs, szs, sigs, pubs, shas, res, n );
    for( ulong j=0; j<n; j++ ) FD_TEST( res[j]==FD_ED25519_SUCCESS );
    long dt = fd_log_wallclock();
    for( ulong rem=iter; rem; rem-- ) {
      FD_COMPILER_FORGET( pm ); FD_COMPILER_FORGET( pz ); FD_COMPILER_FORGET( ps ); FD_COMPILER_FORGET( pp ); FD_COMPILER_FORGET( n );
      fd_ed25519_verify_batch_multi_msg( pm, pz, ps, pp, shas, res, n );
    }
    dt = fd_log_wallclock() - dt;
    log_bench( fd_cstr_printf( cstr, 128UL, NULL, "verify_batch_multi_msg(128) n=%lu", n ), iter*n, dt );
    /* the keys enter the cache on their second passing verify */
    for( ulong pass=0; pass<3UL; pass++ ) fd_ed25519_verify_batch_multi_msg_cached( msgs, szs, sigs, pubs, shas, res, n, cache );
    for( ulong j=0; j<n; j++ ) FD_TEST( res[j]==FD_ED25519_SUCCESS );
    dt = fd_log_wallclock();
    for( ulong rem=iter; rem; rem-- ) {
      FD_COMPILER_FORGET( pm ); FD_COMPILER_FORGET( pz ); FD_COMPILER_FORGET( ps ); FD_COMPILER_FORGET( pp ); FD_COMPILER_FORGET( n );
      fd_ed25519_verify_batch_multi_msg_cached( pm, pz, ps, pp, shas, res, n, cache );
    }
    dt = fd_log_wallclock() - dt;
    log_bench( fd_cstr_printf( cstr, 128UL, NULL, "verify_batch_multi_msg_cached(128) n=%lu", n ), iter*n, dt );
  }
  FD_LOG_NOTICE(( "  cache: %lu hits, %lu misses, %lu inserts", fd_ed25519_cache_hit_cnt( cache ), fd_ed25519_cache_miss_cnt( cache ), fd_ed25519_cache_insert_cnt( cache ) ));
  cache_destroy( cache );
}

int
main( int     argc,
      char ** argv ) {
  fd_boot( &argc, &argv );
  g_bench      = fd_env_strip_cmdline_contains( &argc, &argv, "--bench" );
  ulong rounds = fd_env_strip_cmdline_ulong( &argc, &argv, "--rounds", NULL, 3UL );
  uint  seed   = fd_env_strip_cmdline_uint ( &argc, &argv, "--seed",   NULL, 0U  );
  fd_rng_t _rng[1]; fd_rng_t * rng = fd_rng_join( fd_rng_new( _rng, seed, 0UL ) );
  fd_sha512_t _sha[BATCH_MAX]; fd_sha512_t * shas[BATCH_MAX];
  for( ulong j=0; j<BATCH_MAX; j++ ) shas[j] = fd_sha512_join( fd_sha512_new( &_sha[j] ) );

  fd_ed25519_cache_t * cache = cache_create( 64UL, 1UL );
  /* an empty batch reads nothing */
  fd_ed25519_verify_batch_multi_msg( NULL, NULL, NULL, NULL, NULL, NULL, 0UL );
  fd_ed25519_verify_batch_multi_msg_cached( NULL, NULL, NULL, NULL, NULL, NULL, 0UL, cache );

  test_vectors( rng, shas, cache );
  test_random( rng, shas, cache, rounds );
  FD_LOG_NOTICE(( "cache of 64: %lu hits, %lu misses, %lu inserts", fd_ed25519_cache_hit_cnt( cache ), fd_ed25519_cache_miss_cnt( cache ), fd_ed25519_cache_insert_cnt( cache ) ));
  FD_TEST( fd_ed25519_cache_hit_cnt( cache ) && fd_ed25519_cache_insert_cnt( cache ) );
  cache_destroy( cache );

  /* the smallest cache: the keys of the random batches replace each other */
  cache = cache_create( 4UL, 2UL );
  test_random( rng, shas, cache, 1UL );
  FD_LOG_NOTICE(( "cache of 4: %lu hits, %lu misses, %lu inserts", fd_ed25519_cache_hit_cnt( cache ), fd_ed25519_cache_miss_cnt( cache ), fd_ed25519_cache_insert_cnt( cache ) ));
  FD_TEST( fd_ed25519_cache_hit_cnt( cache ) && fd_ed25519_cache_insert_cnt( cache ) );
  cache_destroy( cache );

  if( g_bench ) bench( rng, shas );

  for( ulong j=0; j<BATCH_MAX; j++ ) fd_sha512_delete( fd_sha512_leave( shas[j] ) );
  fd_rng_delete( fd_rng_leave( rng ) );
  FD_LOG_NOTICE(( "pass" ));
  fd_halt();
  return 0;
}
